import{_ as t,o as a,c as r,a0 as s}from"./chunks/framework.CIWPqrYr.js";const i="/manual/assets/04-task-drawer.CgsLNKpL.png",p=JSON.parse('{"title":"3. Managing Tasks","description":"","frontmatter":{},"headers":[],"relativePath":"03-managing-tasks.md","filePath":"03-managing-tasks.md"}'),n={name:"03-managing-tasks.md"};function o(l,e,h,c,g,d){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="_3-managing-tasks" tabindex="-1">3. Managing Tasks <a class="header-anchor" href="#_3-managing-tasks" aria-label="Permalink to &quot;3. Managing Tasks&quot;">​</a></h1><p>Tasks are the fundamental units of work. This section covers creating and tracking your work from start to finish.</p><h2 id="creating-a-task" tabindex="-1">Creating a Task <a class="header-anchor" href="#creating-a-task" aria-label="Permalink to &quot;Creating a Task&quot;">​</a></h2><ol><li>On any board, click the <strong>New Task</strong> button at the top right, OR press <code>C</code> on your keyboard.</li><li>Enter a descriptive title and press <code>Enter</code>. The task will appear in your first column.</li></ol><h2 id="the-task-drawer" tabindex="-1">The Task Drawer <a class="header-anchor" href="#the-task-drawer" aria-label="Permalink to &quot;The Task Drawer&quot;">​</a></h2><p>Clicking on a task card opens the <strong>Task Drawer</strong>, a detailed view where all collaboration happens.</p><p><img src="'+i+'" alt="Task Drawer View"></p><h3 id="_1-rich-text-attachments" tabindex="-1">1. Rich Text &amp; Attachments <a class="header-anchor" href="#_1-rich-text-attachments" aria-label="Permalink to &quot;1. Rich Text &amp; Attachments&quot;">​</a></h3><p>The description field uses a powerful WYSIWYG editor.</p><ul><li><strong>Formatting</strong>: You can highlight text to use the formatting toolbar, or use standard Markdown shortcuts (e.g., typing <code># </code> creates a heading, <code>* </code> creates a bulleted list).</li><li><strong>Mentions</strong>: Type <code>@</code> to tag teammates; they will receive an Inbox notification.</li><li><strong>Attachments</strong>: Drag and drop images, PDFs, or documents directly into the description or the comment area to attach them to the task.</li></ul><h3 id="_2-properties-right-panel" tabindex="-1">2. Properties (Right Panel) <a class="header-anchor" href="#_2-properties-right-panel" aria-label="Permalink to &quot;2. Properties (Right Panel)&quot;">​</a></h3><ul><li><strong>Assignees</strong>: Delegate the task to one or more team members.</li><li><strong>Status</strong>: Move the task through its lifecycle (equivalent to dragging it across the board).</li><li><strong>Priority &amp; Due Date</strong>: Set urgency and deadlines to keep work on track.</li><li><strong>Story Points / Estimates</strong>: Input a numerical value (e.g., 3, 5, 8) to represent the effort required. This data is critical for generating Burndown charts in the Reports view.</li></ul><h3 id="_3-checklists-dependencies" tabindex="-1">3. Checklists &amp; Dependencies <a class="header-anchor" href="#_3-checklists-dependencies" aria-label="Permalink to &quot;3. Checklists &amp; Dependencies&quot;">​</a></h3><ul><li><strong>Checklists</strong>: Break the task into smaller sub-items.</li><li><strong>Dependencies</strong>: If Task A must be finished before Task B, link them! In the Task Drawer, click <strong>Link Task</strong>, select the blocking task, and set the relationship to &quot;Blocks&quot; or &quot;Is Blocked By&quot;. <ul><li><em>What happens when a blocker is completed?</em> When the blocking task is moved to the &quot;Done&quot; stage, the assignees of the blocked task will automatically receive an Inbox notification alerting them that they are now unblocked and can begin work.</li></ul></li></ul><h2 id="deleting-or-archiving-tasks" tabindex="-1">Deleting or Archiving Tasks <a class="header-anchor" href="#deleting-or-archiving-tasks" aria-label="Permalink to &quot;Deleting or Archiving Tasks&quot;">​</a></h2><p>If a task was created by mistake or is no longer relevant:</p><ol><li>Open the Task Drawer.</li><li>Click the <strong>...</strong> (Options) menu in the top right.</li><li>Select <strong>Archive</strong> to hide it from the active board but keep the record, or <strong>Delete</strong> to permanently remove it (Admin only).</li></ol>',17)])])}const m=t(n,[["render",o]]);export{p as __pageData,m as default};
